def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    # Long matching-color bars at opposing edges define rays. Copy the isolated marker
    # on the ray line across the rectangle, recoloring the marker's originating point.
    bars=[]
    for i,row in enumerate(g):
        vals=[v for v in row if v!=0]
        if len(vals)>=2 and len(set(vals))==1:
            bars.append(('h',i,vals[0], min(j for j,v in enumerate(row) if v!=0), max(j for j,v in enumerate(row) if v!=0)))
    for j in range(w):
        vals=[g[i][j] for i in range(h) if g[i][j]!=0]
        if len(vals)>=2 and len(set(vals))==1:
            bars.append(('v',j,vals[0], min(i for i in range(h) if g[i][j]!=0), max(i for i in range(h) if g[i][j]!=0)))
    # Identify color of background, and single-cell marker color.
    from collections import Counter
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    for axis,pos,color,a,b in bars:
        if axis=='h':
            # markers between horizontal bars, project perpendicular between their x coordinates
            for i in range(h):
                for j in range(w):
                    if g[i][j] not in (bg,color):
                        c=g[i][j]
                        if i not in (pos,):
                            for r in range(min(i,pos),max(i,pos)+1):
                                if g[r][j]==bg: g[r][j]=c
        else:
            for i in range(h):
                for j in range(w):
                    if g[i][j] not in (bg,color):
                        c=g[i][j]
                        for col in range(min(j,pos),max(j,pos)+1):
                            if g[i][col]==bg:g[i][col]=c
    return g
